/**
 * The digest: the only view of the save the model ever sees.
 *
 * Two hard constraints shape this file.
 *
 * 1. SIZE. The save will grow to hundreds of KB over a long run. Handing that
 *    to the model every turn costs tokens, latency, and accuracy — a model
 *    reading 300 KB of JSON starts summarising instead of reasoning. The digest
 *    is capped and prioritised: position and immediate stakes first, history
 *    last and truncated.
 *
 * 2. AUTHORITY. Everything in the digest is computed by the engine from the
 *    save. The model may quote it, reorder it, and turn it into prose. It may
 *    not add a fact that is not here. That is the whole contract.
 *
 * Every tool returns a fresh digest, because the alternative is one extra model
 * round-trip per turn to re-read state — which on this platform turns a 2-second
 * turn into a 5-second one for no benefit.
 */

import { dispositionOf, stanceLabel } from './people.js'
import { describe as describeDrift } from './destiny.js'
import { formatDate, eraOf } from './clock.js'
import { playerPower } from './world.js'

/** Hard caps. Chosen so a digest lands around 1.5–3 KB of Chinese text. */
export const LIMITS = {
  people: 4,
  memoriesPerPerson: 3,
  recentEvents: 6,
  options: 6
}

/**
 * Build the digest.
 *
 * @param {object} state  save
 * @param {object} [extra] engine-computed additions for THIS turn only
 *   (the outcome of the action just resolved, the options now on offer)
 */
export function buildDigest(state, extra = {}) {
  const player = state.player ?? {}
  const resources = player.resources ?? {}
  const counters = player.counters ?? {}
  const clock = state.clock ?? {}

  const digest = {
    when: eraOf(clock.year ?? 184).length > 0
      ? `${formatDate(clock)}（${eraOf(clock.year)}）`
      : formatDate(clock),
    age: Number.isFinite(state.age) ? state.age : clock.age ?? 0,
    act: state.actName ?? state.act ?? '',
    place: state.place ?? '',
    me: {
      name: player.name ?? '刘备',
      courtesy: player.courtesy ?? '玄德',
      titles: Array.isArray(player.titles) && player.titles.length > 0 ? player.titles : ['布衣'],
      attrs: player.attrs ?? {},
      counters: {
        fame: counters.fame ?? 0,
        trust: counters.trust ?? 0,
        talent: counters.talent ?? 0
      },
      resources: {
        troops: resources.troops ?? 0,
        gold: resources.gold ?? 0,
        grain: resources.grain ?? 0,
        hp: resources.hp ?? 100
      },
      power: playerPower(state)
    },
    world: {
      mood: describeDrift(state.drift ?? 0),
      drift: Number.isFinite(state.drift) ? state.drift : 0
    },
    people: nearestPeople(state),
    recent: recentEvents(state)
  }

  if (extra.outcome !== undefined) {
    digest.outcome = extra.outcome
  }
  if (Array.isArray(extra.options) && extra.options.length > 0) {
    digest.options = extra.options.slice(0, LIMITS.options)
  }
  if (Array.isArray(extra.events) && extra.events.length > 0) {
    digest.events = extra.events.slice(0, LIMITS.recentEvents)
  }
  if (typeof extra.narrationHint === 'string' && extra.narrationHint.length > 0) {
    digest.narrationHint = extra.narrationHint
  }
  if (typeof extra.pending !== 'undefined' && extra.pending !== null) {
    digest.pending = extra.pending
  }

  return digest
}

/**
 * The people who matter right now: those the player has met, sorted by how
 * much they care (absolute disposition), capped.
 *
 * Sorting by absolute value rather than by warmth is deliberate: someone who
 * hates you is more dramatically relevant than someone who is indifferent, and
 * a digest that only surfaces friends hides the consequences of betrayal.
 */
export function nearestPeople(state) {
  const people = state.people ?? {}
  const rows = []
  for (const id of Object.keys(people)) {
    const person = people[id]
    if (person?.met !== true) continue
    const disposition = dispositionOf(person)
    rows.push({ person, disposition, magnitude: Math.abs(disposition) })
  }
  rows.sort((a, b) => b.magnitude - a.magnitude)
  return rows.slice(0, LIMITS.people).map((row) => ({
    name: row.person.name,
    stance: stanceLabel(row.disposition),
    disposition: row.disposition,
    mood: row.person.mood,
    remembers: (row.person.memories ?? [])
      .slice(-LIMITS.memoriesPerPerson)
      .map((memory) => memory.text)
  }))
}

/** The last few things that happened, oldest first. */
export function recentEvents(state) {
  const log = Array.isArray(state.log) ? state.log : []
  return log.slice(-LIMITS.recentEvents).map((entry) => entry.text ?? '')
}

/**
 * Render the digest as compact text.
 *
 * Used when a tool wants a human-readable summary alongside the structured
 * value. The structured form is what the model reasons over; this form is what
 * it can paste into prose without reformatting.
 */
export function renderDigest(digest) {
  const lines = []
  lines.push(`${digest.when} · ${digest.age}岁 · ${digest.act}`)
  const me = digest.me
  lines.push(
    `我：${me.name}　兵力 ${me.resources.troops}　金 ${me.resources.gold}　粮 ${me.resources.grain}　` +
    `实力 ${me.power}`
  )
  // 势 is reserved for DRIFT (the price of departing from history). The player's
  // own rating is 实力. Overloading the word made the digest read "势 34" while
  // the world mood said 天下未觉, which is a contradiction the model had no way
  // to resolve.
  lines.push(
    `名望 ${me.counters.fame}　信义 ${me.counters.trust}　人才 ${me.counters.talent}　` +
    `势 ${digest.world.drift}（${digest.world.mood}）`
  )
  if (digest.people.length > 0) {
    lines.push(`在场/相关：${digest.people.map((p) => `${p.name}（${p.stance}）`).join('、')}`)
  }
  if (digest.recent.length > 0) {
    lines.push(`近事：${digest.recent.join('；')}`)
  }
  return lines.join('\n')
}
